//! Native result-level three-system benchmark. Explicit execution only; no provider calls on validation.
use crate::{Result,canonical::{canonical,sha256}};
use serde_json::{Value,json};
use std::{collections::{BTreeMap,BTreeSet},path::{Path,PathBuf},io::Write};
pub mod validators;
mod external;
pub use external::{HermesAdapter,OpenClawAdapter};
pub const SYSTEMS:[&str;3]=["ai_platform","hermes","openclaw"];
pub fn repo_root()->PathBuf{std::env::var_os("AI_PLATFORM_REPO_ROOT").map(PathBuf::from).unwrap_or_else(||Path::new(env!("CARGO_MANIFEST_DIR")).ancestors().nth(4).expect("workspace layout").to_path_buf())}
pub fn default_manifest()->PathBuf{repo_root().join("src/services/eval/fixtures/native_agent_parity_v1/manifest.json")}
pub fn sha256_file(path:&Path)->Result<String>{Ok(sha256(&std::fs::read(path)?))}
pub fn private_directory(path:&Path)->Result<()>{std::fs::create_dir_all(path)?;#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;std::fs::set_permissions(path,std::fs::Permissions::from_mode(0o700))?;}Ok(())}
pub fn write_private_json(path:&Path,value:&Value)->Result<()>{if let Some(parent)=path.parent(){private_directory(parent)?}let mut options=std::fs::OpenOptions::new();options.write(true).create(true).truncate(true);#[cfg(unix)]{use std::os::unix::fs::OpenOptionsExt;options.mode(0o600).custom_flags(libc::O_NOFOLLOW);}let mut file=options.open(path)?;#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;file.set_permissions(std::fs::Permissions::from_mode(0o600))?;}file.write_all(serde_json::to_string_pretty(value)?.as_bytes())?;file.write_all(b"\n")?;Ok(())}
pub fn safe_repo_path(relative:&str)->Result<PathBuf>{let root=repo_root().canonicalize()?;let path=root.join(relative).canonicalize().map_err(|_|"fixture_path_missing")?;if !path.starts_with(&root){return Err("fixture_path_escapes_repository".into())}if !path.is_file(){return Err("fixture_path_missing".into())}Ok(path)}
pub fn load_manifest(path:&Path)->Result<Value>{let bytes=std::fs::read(path).map_err(|_|"manifest_unreadable:OSError")?;let m:Value=serde_json::from_slice(&bytes).map_err(|_|"manifest_unreadable:JSONDecodeError")?;validate_manifest(&m)?;Ok(m)}
pub fn validate_manifest(m:&Value)->Result<()>{if m["schema_version"]!="native-agent-parity/v1"{return Err("unsupported_manifest_schema".into())}if m["systems"]!=json!(SYSTEMS){return Err("systems_must_use_official_three_way_order".into())}if !["off","low","medium","high"].contains(&text(&m["thinking_level"])){return Err("manifest_requires_explicit_thinking_level".into())}if !["safe","balanced","power"].contains(&text(&m["execution_profile"])){return Err("manifest_requires_explicit_execution_profile".into())}if m["max_approval_rounds"].as_u64().is_none_or(|n|!(1..=32).contains(&n)){return Err("manifest_requires_bounded_max_approval_rounds".into())}let tasks=m["tasks"].as_array().filter(|a|(8..=12).contains(&a.len())).ok_or("manifest_requires_8_to_12_tasks")?;let mut seen=BTreeSet::new();for t in tasks{let id=text(&t["task_id"]);if id.is_empty()||!seen.insert(id){return Err("task_ids_must_be_unique_nonempty_strings".into())}if !["finance_golden","governed_export","python_reserve","scenario_assertions","staged_rollout","tenant_access","unknown_effect"].contains(&text(&t["validator"])){return Err(format!("unsupported_validator:{id}").into())}if !["text","json"].contains(&text(&t["output_format"])){return Err(format!("unsupported_output_format:{id}").into())}let turns=t["turns"].as_array().filter(|a|!a.is_empty()).ok_or_else(||format!("task_requires_turns:{id}"))?;for turn in turns{if !turn.is_object()||!(turn["prompt"].is_string()||(turn["scenario_path"].is_string()&&turn["scenario_id"].is_string())){return Err(format!("invalid_turn:{id}").into())}if !turn["expected"].is_object(){return Err(format!("missing_turn_oracle:{id}").into())}}}Ok(())}
pub fn load_scenario(turn:&Value)->Result<Value>{let path=safe_repo_path(text(&turn["scenario_path"]))?;let bytes=std::fs::read(path).map_err(|_|"scenario_unreadable:OSError")?;let suite:Value=serde_json::from_slice(&bytes).map_err(|_|"scenario_unreadable:JSONDecodeError")?;let list=suite["scenarios"].as_array().ok_or("scenario_suite_missing_scenarios")?;let matches:Vec<_>=list.iter().filter(|v|v["scenario_id"]==turn["scenario_id"]).collect();if matches.len()!=1{return Err("scenario_id_not_unique".into())}Ok(matches[0].clone())}
pub fn neutral_scenario_prompt(prompt:&str)->Result<String>{let replacement="\nWORK METHOD\nAll authoritative evidence for this task is inline. Do not browse, create files, or invoke document-generation tools. You may use native calculation or code execution when needed. No particular delegation primitive or agent identifier is required. Return the requested final work product directly in the response. When the output contract requires a FINAL_JSON block, emit that block before any optional prose so the required artifact cannot be lost to a length limit.\n\n";let mut normalized=prompt.to_owned();let mut count=0;for(pattern,header)in[(r"(?s)\nDELEGATION CONTRACT\n.*?\nFIXED PRIMARY-SOURCE SNAPSHOT\n","FIXED PRIMARY-SOURCE SNAPSHOT\n"),(r"(?s)\nDELEGATION REQUIREMENT\n.*?\nSCENARIO FACTS\n","SCENARIO FACTS\n"),(r"(?s)\nDELEGATION:.*?\n\nCLIENT QUESTION:","CLIENT QUESTION:")]{let regex=regex::Regex::new(pattern)?;if regex.is_match(&normalized){count+=1;normalized=regex.replacen(&normalized,1,regex::NoExpand(&format!("{replacement}{header}"))).into_owned();}}if count!=1{return Err("scenario_delegation_boundary_not_unique".into())}if ["spawn_subagent","agent_id=","exact agent_id"].iter().any(|s|normalized.contains(s)){return Err("scenario_still_requires_product_specific_orchestration".into())}Ok(format!("{}\n\nFINAL DELIVERY PRIORITY\nEmit the required FINAL_JSON block first and in full. Add any optional memo prose only after that complete block.\n",normalized.trim_end()))}
pub fn turn_prompt(turn:&Value)->Result<String>{if let Some(prompt)=turn["prompt"].as_str(){return Ok(prompt.into())}let scenario=load_scenario(turn)?;let prompt=scenario["prompt"].as_str().filter(|s|!s.is_empty()).ok_or("scenario_prompt_missing")?;let normalized=neutral_scenario_prompt(prompt)?;if scenario["output_conformance_hints"].is_null(){return Ok(normalized)}let hints=scenario["output_conformance_hints"].as_array().filter(|a|a.len()<=32&&a.iter().all(|v|v.as_str().is_some_and(|s|!s.trim().is_empty()&&s.chars().count()<=1000))).ok_or("scenario_output_conformance_hints_invalid")?;if hints.is_empty(){return Ok(normalized)}Ok(format!("{}\n\nHOST-SPECIFIED OUTPUT LITERALS\n{}\n",normalized.trim_end(),hints.iter().map(|v|format!("- {}",text(v).trim())).collect::<Vec<_>>().join("\n")))}
pub fn parse_json_work_product(raw:&str)->Result<Value>{let regex=regex::Regex::new(r"(?is)```(?:json)?\s*(.*?)\s*```")?;let captures:Vec<_>=regex.captures_iter(raw.trim()).collect();if captures.len()>1{return Err("candidate_output_has_multiple_json_work_products".into())}let candidate=captures.first().map(|c|c.get(1).unwrap().as_str().trim()).unwrap_or(raw.trim());let value:Value=serde_json::from_str(candidate).map_err(|_|"candidate_output_is_not_one_json_object")?;if !value.is_object(){return Err("candidate_output_is_not_one_json_object".into())}Ok(value)}
pub fn evidence_receipt(path:&Path,manifest:&Value)->Result<Value>{let mut paths=BTreeSet::new();for t in manifest["tasks"].as_array().into_iter().flatten(){for turn in t["turns"].as_array().into_iter().flatten(){for value in [&turn["scenario_path"],&turn["expected"]["golden_path"]]{if let Some(s)=value.as_str(){paths.insert(safe_repo_path(s)?);}}}}let root=repo_root().canonicalize()?;let mut assets=vec![];for p in paths{assets.push(json!({"path":p.strip_prefix(&root)?.to_string_lossy(),"sha256":sha256_file(&p)?}));}Ok(json!({"runner_sha256":sha256_file(&std::env::current_exe()?)?,"manifest_sha256":sha256_file(path)?,"referenced_assets":assets}))}
pub(super) fn text(v:&Value)->&str{v.as_str().unwrap_or("")}
pub(super) fn truthy(v:&Value)->bool{match v{Value::Null=>false,Value::Bool(b)=>*b,Value::Number(n)=>n.as_f64()!=Some(0.0),Value::String(s)=>!s.is_empty(),Value::Array(a)=>!a.is_empty(),Value::Object(o)=>!o.is_empty()}}
pub(super) fn first<'a>(values:&[&'a Value])->&'a Value{values.iter().copied().find(|v|truthy(v)).unwrap_or(&Value::Null)}
#[derive(Clone)]pub struct RuntimeInputs{pub api_key:String,pub password:String,pub email:String,pub provider_base_url:String}
pub fn load_runtime_inputs(path:&Path)->Result<RuntimeInputs>{let mut file=BTreeMap::new();if path.exists(){for item in dotenvy::from_path_iter(path)?{let(k,v)=item?;file.insert(k,v);}}let value=|names:&[&str]|->String{names.iter().find_map(|n|std::env::var(n).ok().filter(|s|!s.is_empty()).or_else(||file.get(*n).filter(|s|!s.is_empty()).cloned())).unwrap_or_default()};let api_key=value(&["DASHSCOPE_CHAT_API_KEY","DASHSCOPE_API_KEY"]);let password=value(&["DEFAULT_USER_PASSWORD"]);let mut domain=value(&["AUTH_ALLOWED_EMAIL_DOMAIN"]);if domain.is_empty(){domain="example.com".into()}let mut base=value(&["DASHSCOPE_CHAT_BASE_URL"]);if base.is_empty(){base="https://dashscope-intl.aliyuncs.com/compatible-mode".into()}base=base.trim_end_matches('/').into();if !base.ends_with("/v1"){base.push_str("/v1")}if api_key.is_empty(){return Err("dashscope_key_missing".into())}if password.is_empty(){return Err("gateway_password_missing".into())}if !base.starts_with("https://"){return Err("provider_base_url_must_be_https".into())}Ok(RuntimeInputs{api_key,password,email:format!("admin@{domain}"),provider_base_url:base})}
pub struct SuiteOptions{pub reserve_sandbox_contract:Option<PathBuf>,pub manifest_path:PathBuf,pub output_dir:PathBuf,pub gateway_base_url:String,pub env_path:PathBuf,pub selected_systems:Vec<String>,pub selected_tasks:Option<BTreeSet<String>>,pub thinking_level_override:Option<String>}
enum Adapter{Platform(crate::parity_benchmark::AIPlatformAdapter),Hermes(HermesAdapter),OpenClaw(OpenClawAdapter)}
impl Adapter{async fn new(system:&str,temp:&Path,runtime:&RuntimeInputs,m:&Value,gateway:&str)->Result<Self>{let model=text(&m["model_id"]);let temperature=m["temperature"].as_f64().ok_or("manifest_temperature_invalid")?;let max_tokens=m["max_tokens"].as_u64().ok_or("manifest_max_tokens_invalid")?;let thinking=text(&m["thinking_level"]);Ok(match system{"ai_platform"=>Self::Platform(crate::parity_benchmark::AIPlatformAdapter::new(crate::parity_benchmark::AdapterConfig{gateway_base_url:gateway.into(),email:runtime.email.clone(),password:runtime.password.clone(),model_id:model.into(),temperature,max_tokens,thinking_level:thinking.into(),execution_profile:text(&m["execution_profile"]).into(),max_approval_rounds:m["max_approval_rounds"].as_u64().unwrap()as usize,task_output_formats:m["tasks"].as_array().unwrap().iter().map(|t|(text(&t["task_id"]).into(),text(&t["output_format"]).into())).collect()}).await?),"hermes"=>Self::Hermes(HermesAdapter::new(temp.join(system),&runtime.api_key,&runtime.provider_base_url,model,temperature,max_tokens,thinking)?),"openclaw"=>Self::OpenClaw(OpenClawAdapter::new(temp.join(system),&runtime.api_key,&runtime.provider_base_url,model,temperature,max_tokens,thinking)?),_=>return Err(format!("unknown_system:{system}").into())})}async fn start_task(&mut self,id:&str)->Result<()>{match self{Self::Platform(a)=>a.start_task(id).await,Self::Hermes(a)=>a.start_task(id).await,Self::OpenClaw(a)=>a.start_task(id).await}}async fn turn(&mut self,id:&str,prompt:&str)->Result<crate::parity_benchmark::TurnResult>{match self{Self::Platform(a)=>a.run_turn(id,prompt).await,Self::Hermes(a)=>a.run_turn(id,prompt).await,Self::OpenClaw(a)=>a.run_turn(id,prompt).await}}}
pub async fn run_suite(options:SuiteOptions)->Result<Value>{let mut manifest=load_manifest(&options.manifest_path)?;let manifest_thinking=manifest["thinking_level"].clone();if let Some(thinking)=&options.thinking_level_override{if !["off","low","medium","high"].contains(&thinking.as_str()){return Err("invalid_thinking_level_override".into())}manifest["thinking_level"]=json!(thinking)}let runtime=load_runtime_inputs(&options.env_path)?;if options.output_dir.exists(){return Err("output_directory_exists".into())}private_directory(&options.output_dir)?;let tasks:Vec<_>=manifest["tasks"].as_array().unwrap().iter().filter(|t|options.selected_tasks.as_ref().is_none_or(|ids|ids.contains(text(&t["task_id"])))).collect();if tasks.is_empty(){return Err("no_selected_tasks".into())}let reserve_executor=if tasks.iter().any(|t|t["validator"]=="python_reserve"){let contract=options.reserve_sandbox_contract.as_ref().ok_or("python_reserve_requires_pinned_sandbox_contract_before_provider_execution")?;Some(crate::python_work_product::PythonWorkProduct::prepare(contract).await?)}else{None};let started_at=chrono::Utc::now().to_rfc3339();let mut receipts=vec![];let temp=tempfile::Builder::new().prefix("native-agent-parity-").tempdir()?;private_directory(temp.path())?;for system in &options.selected_systems{let mut adapter=Adapter::new(system,temp.path(),&runtime,&manifest,&options.gateway_base_url).await?;for task in &tasks{let id=text(&task["task_id"]);adapter.start_task(id).await?;let mut turns=vec![];let mut task_passed=true;for(index,turn)in task["turns"].as_array().unwrap().iter().enumerate(){let result:Result<Value>=async{let output=adapter.turn(id,&turn_prompt(turn)?).await?;let mut validation_execution=Value::Null;let(passed,reason,parsed)=if task["validator"]=="python_reserve"{let parsed=parse_json_work_product(&output.text)?;let(passed,reason,execution)=reserve_executor.as_ref().ok_or("python_reserve_executor_missing")?.validate(&parsed,&turn["expected"]).await?;validation_execution=execution;(passed,reason,Some(parsed))}else{validators::validate_turn(text(&task["validator"]),&output.text,&turn["expected"],Some(turn))?};Ok(json!({"ordinal":index+1,"passed":passed,"reason":reason,"duration_seconds":(output.duration_seconds*1000.0).round_ties_even()/1000.0,"terminal_status":output.terminal_status,"output":output.text,"output_sha256":sha256(output.text.as_bytes()),"parsed_output":parsed,"validation_execution":validation_execution,"metadata":output.metadata}))}.await;let receipt=match result{Ok(v)=>v,Err(e)=>json!({"ordinal":index+1,"passed":false,"reason":e.to_string(),"duration_seconds":null,"terminal_status":"infrastructure_error","output":"","output_sha256":sha256(b""),"parsed_output":null,"metadata":{}})};let passed=receipt["passed"]==true;turns.push(receipt);if !passed{task_passed=false;break}}let receipt=json!({"system":system,"task_id":id,"domain":task["domain"],"passed":task_passed&&turns.len()==task["turns"].as_array().unwrap().len(),"turns":turns});write_private_json(&options.output_dir.join(format!("{system}__{id}.json")),&receipt)?;println!("{system:11} {id:42} {}",if receipt["passed"]==true{"PASS"}else{"FAIL"});receipts.push(receipt);}}drop(temp);let mut counts=json!({});for system in &options.selected_systems{let selected:Vec<_>=receipts.iter().filter(|v|v["system"]==*system).collect();let passed=selected.iter().filter(|v|v["passed"]==true).count();let errors=selected.iter().filter(|v|v["turns"].as_array().unwrap().iter().any(|t|t["terminal_status"]=="infrastructure_error")).count();counts[system]=json!({"passed":passed,"total":selected.len(),"infrastructure_errors":errors,"completion_rate":if selected.is_empty(){0.0}else{passed as f64/selected.len()as f64}})}let acceptance=options.selected_systems==SYSTEMS&&tasks.len()==manifest["tasks"].as_array().unwrap().len()&&SYSTEMS.iter().all(|s|counts[s]["infrastructure_errors"]==0)&&counts["ai_platform"]["passed"].as_u64().is_some_and(|n|n>0)&&counts["ai_platform"]["completion_rate"].as_f64()>=counts["hermes"]["completion_rate"].as_f64()&&counts["ai_platform"]["completion_rate"].as_f64()>=counts["openclaw"]["completion_rate"].as_f64();let summary=json!({"schema_version":"native-agent-parity-result/v1","suite_id":manifest["suite_id"],"manifest_sha256":sha256_file(&options.manifest_path)?,"started_at":started_at,"finished_at":chrono::Utc::now().to_rfc3339(),"model_id":manifest["model_id"],"temperature":manifest["temperature"],"max_tokens":manifest["max_tokens"],"thinking_level":manifest["thinking_level"],"manifest_thinking_level":manifest_thinking,"thinking_level_override_applied":options.thinking_level_override.is_some(),"execution_profile":manifest["execution_profile"],"evidence":evidence_receipt(&options.manifest_path,&manifest)?,"versions":external::version_receipts().await?,"counts":counts,"acceptance_passed":acceptance,"task_results":receipts.iter().map(|v|json!({"system":v["system"],"task_id":v["task_id"],"passed":v["passed"]})).collect::<Vec<_>>()});write_private_json(&options.output_dir.join("summary.json"),&summary)?;Ok(summary)}
#[cfg(test)]mod tests{use super::*;#[test]fn manifest_requires_order_bounded_approvals_and_unique_tasks(){let mut m=json!({"schema_version":"native-agent-parity/v1","systems":SYSTEMS,"thinking_level":"off","execution_profile":"safe","max_approval_rounds":1,"tasks":(0..8).map(|i|json!({"task_id":format!("t{i}"),"validator":"tenant_access","output_format":"json","turns":[{"prompt":"test","expected":{}}]})).collect::<Vec<_>>()});assert!(validate_manifest(&m).is_ok());m["max_approval_rounds"]=json!(true);assert!(validate_manifest(&m).is_err());m["max_approval_rounds"]=json!(1);m["tasks"][1]["task_id"]=json!("t0");assert!(validate_manifest(&m).is_err());}
#[test]fn parser_accepts_one_object_and_rejects_ambiguous_work_products(){assert_eq!(parse_json_work_product("```json\n{\"x\":1}\n```").unwrap(),json!({"x":1}));assert!(parse_json_work_product("```json\n{}\n```\n```json\n{}\n```").is_err());assert!(parse_json_work_product("[]").is_err());}
#[test]fn neutralization_requires_exactly_one_orchestration_boundary(){let input="TASK\nDELEGATION REQUIREMENT\nspawn_subagent exact agent_id\nSCENARIO FACTS\nfixed";let output=neutral_scenario_prompt(input).unwrap();assert!(output.contains("WORK METHOD"));assert!(output.contains("SCENARIO FACTS\nfixed"));assert!(!output.contains("spawn_subagent"));assert!(neutral_scenario_prompt("no boundary").is_err());}
#[test]fn private_receipts_round_trip_without_following_symlinks(){let temp=tempfile::tempdir().unwrap();let path=temp.path().join("receipt.json");write_private_json(&path,&json!({"passed":true})).unwrap();assert_eq!(serde_json::from_slice::<Value>(&std::fs::read(&path).unwrap()).unwrap()["passed"],true);#[cfg(unix)]{use std::os::unix::fs::{PermissionsExt,symlink};assert_eq!(std::fs::metadata(&path).unwrap().permissions().mode()&0o777,0o600);let link=temp.path().join("linked.json");symlink(&path,&link).unwrap();assert!(write_private_json(&link,&json!({})).is_err());}}
}
